css:
@page { size: A4 landscape; margin: 10mm 12mm; }
* { box-sizing: border-box; }
body { margin: 0; font-family: 'Inter', Arial, Helvetica, sans-serif; color: #1A1A1A; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.rtr-page { padding: 4mm 2mm; zoom: 0.9; }
.rtr-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #DA251C; padding-bottom: 10px; margin-bottom: 12px; }
.rtr-header img { height: 44px; }
.rtr-title-block { text-align: right; }
.rtr-title { font-size: 16px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #1A1A1A; }
.rtr-meta-line { font-size: 10px; color: #4A4A4A; margin-top: 3px; }
table.rtr-table { width: 100%; border-collapse: collapse; font-size: 9px; color: #1A1A1A; }
table.rtr-table td, table.rtr-table th { border: 1px solid #DCDCDC; padding: 5px 6px; font-weight: 400; }
.rtr-label-cell { background: #F6F6F6; font-weight: 600; padding: 5px 8px; }
.rtr-group-cell { background: #F6F6F6; font-weight: 600; padding: 5px 8px; border-bottom: 2px solid #232323 !important; }
.rtr-groupline-top { border-top: 2px solid #232323 !important; border-bottom: 2px solid #232323 !important; }
.rtr-check-on-hdr { text-align: left; font-weight: 600; width: 90px; }
.rtr-test-hdr { text-align: left; font-weight: 600; width: 120px; }
.rtr-req-hdr { text-align: left; font-weight: 600; width: 150px; }
.rtr-val { text-align: center; }
.rtr-val-hdr { text-align: center; font-weight: 600; }
.rtr-group-end td { border-bottom: 2px solid #232323 !important; }
.rtr-footer { border-top: 1px solid #DCDCDC; padding-top: 10px; margin-top: 10px; display: flex; justify-content: space-between; gap: 24px; font-size: 9px; color: #4A4A4A; }
.rtr-footer .rtr-footer-label { font-weight: 600; color: #1A1A1A; }
.rtr-footer-right { text-align: right; }
